                           ("Server/Item/RootInteractions/", "root", ".json"), ("Server/Projectiles/", "prj", ".json"),
                           ("Server/Models/", "model", ".json"), ("Server/Entity/Trails/", "trail", ".json"),
                           ("Server/Audio/SoundEvents/", "sound", ".json"), ("Server/Item/Animations/", "anim", ".json"),
