def aj(kind, aid):
    p = AIDX[kind][aid]
    if p not in AJ:
        AJ[p] = json.loads(AZ.read(p).decode("utf-8-sig"))
    return AJ[p]


def ahas(kind, aid):
    return aid in AIDX.get(kind, {})


def aresolve(kind, aid):
    d = aj(kind, aid)
    if not d.get("Parent"):
        return dict(d)
    base = aresolve(kind, d["Parent"])
    for k, v in d.items():
        if k != "Parent":
            base[k] = v
    return base


