def jump(keys, v):
    """ChargingInteraction.jumpToChargeValue: the key with the smallest (value - key) >= 0 (index into the sorted keys), -1 = none"""
    best, bi = 2147483648.0, -1
    for i, k in enumerate(keys):
        if v < k:
            continue
        d = v - k
        if bi == -1 or d < best:
            best, bi = d, i
    return bi


