def r9_face_bad(md, tw, th, all6=True):
    """own walker: every box needs the 6 faces (all6; vanilla leaves hidden faces out); each face's texel rectangle (angle 0 / 90 / 180 / 270,
    mirror) inside tw x th"""
    bad_, n_ = [], [0]

    def walk(nodes):
        for n in nodes:
            sh = n.get("shape") or {}
            if sh.get("type") == "box":
                n_[0] += 1
                sz = sh["settings"]["size"]
                lay = sh.get("textureLayout") or {}
                for f, (a, b) in R9_FACE.items():
                    l = lay.get(f)
                    if l is None:
                        if all6:
                            bad_.append("%s.%s no layout" % (n["name"], f))
                        continue
                    w, h = float(sz[a]), float(sz[b])
                    mx, my = (l.get("mirror") or {}).get("x"), (l.get("mirror") or {}).get("y")
                    ang = int(l.get("angle", 0)) % 360
                    xs, ys = [], []
                    for u, v in ((0, 0), (w, 0), (w, h), (0, h)):
                        u, v = (-u if mx else u), (-v if my else v)
                        u, v = {0: (u, v), 90: (-v, u), 180: (-u, -v), 270: (v, -u)}[ang]
                        xs.append(l["offset"]["x"] + u)
                        ys.append(l["offset"]["y"] + v)
                    if min(xs) < -1e-6 or min(ys) < -1e-6 or max(xs) > tw + 1e-6 or max(ys) > th + 1e-6:
                        bad_.append("%s.%s x %.1f..%.1f y %.1f..%.1f" % (n["name"], f, min(xs), max(xs), min(ys), max(ys)))
            walk(n.get("children") or [])
    walk(md["nodes"])
    return n_[0], bad_


def r9_version_only(a, b):
    """the two class files differ ONLY inside "0.1.4" (old) -> "0.1.5" (new) texts at the same offsets (same length, same layout); the fixed
    "SkyyArmory 0.1.4" texts of the 0.1.4 migration stay 0.1.4 in both"""
    if len(a) != len(b):
        return False
    for p in range(len(a)):
        if a[p] != b[p] and not any(a[i:i + 5] == b"0.1.4" and b[i:i + 5] == b"0.1.5" for i in range(max(0, p - 4), p + 1)):
            return False
    return True


