    NEW_ROWS += ["hop.hangSeconds", "hop.hangFall", "part.bowtrav", "bow.hopForce", "bow.hangSeconds", "bow.hangFall", "bow.blastRadius", "bow.blastPercent",
                 "bow.stamina", "bow.mana"]      # 0.1.3
    NEW_ROWS += ["part.book", "book.k", "book.range", "book.edgeFalloff", "lev.safeAfter", "lev.crouchLands", "lev.riseSpeed", "lev.floatFall",
                 "part.kunai", "kunai.dpsShare", "kunai.throwRange", "kunai.flightTtl", "kunai.behindMob", "kunai.noArena",
                 "kunai.noCombat", "kunai.pvp", "kunai.maxPerMinute", "ret.force", "ret.damage"]      # 0.1.6 (0.1.7: - kunai.floorCheck)
    NEW_ROWS += ["part.stun", "stun.perPlayer", "stun.maxPlayers", "stun.gap", "stun.window", "stun.bossWords"]      # 0.1.7
